def solve_n_queens(n):
    solutions = []

    def is_safe(placement, row, col):
        for r, c in enumerate(placement):
            if c == col:                        # same column
                return False
            if abs(r - row) == abs(c - col):   # same diagonal
                return False
        return True

    def backtrack(placement):
        row = len(placement)
        if row == n:
            solutions.append(placement[:])
            return
        for col in range(n):
            if is_safe(placement, row, col):
                placement.append(col)
                backtrack(placement)
                placement.pop()

    backtrack([])
    return solutions

solutions = solve_n_queens(4)
print(f"Number of solutions: {len(solutions)}")
for sol in solutions:
    print(f"Solution: {sol}")
    # Visualise
    for row, col in enumerate(sol):
        print("  " + ". " * col + "Q " + ". " * (4 - col - 1))
    print()
